local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Parent = game.Players.LocalPlayer:WaitForChild("PlayerGui")

local Frame = Instance.new("Frame")
Frame.Parent = ScreenGui
Frame.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
Frame.BorderSizePixel = 0
Frame.Position = UDim2.new(0.44, 0, 0.58, 0)
Frame.Size = UDim2.new(0, 400, 0, 180)

Frame.Draggable = true
Frame.Active = true
Frame.Selectable = true

local UICorner = Instance.new("UICorner")
UICorner.Parent = Frame
UICorner.CornerRadius = UDim.new(0, 15)

local UIStroke = Instance.new("UIStroke")
UIStroke.Parent = Frame
UIStroke.Color = Color3.fromRGB(255, 255, 255)
UIStroke.Thickness = 3

local function CreateButton(text, position)
	local Button = Instance.new("TextButton")
	Button.Parent = Frame
	Button.Size = UDim2.new(0, 150, 0, 60)
	Button.Position = position
	Button.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
	Button.TextColor3 = Color3.fromRGB(40, 40, 40)
	Button.Text = text
	Button.TextScaled = true

	local ButtonCorner = Instance.new("UICorner")
	ButtonCorner.Parent = Button
	ButtonCorner.CornerRadius = UDim.new(0, 10)

	return Button
end

local SkyButton = CreateButton("Sky", UDim2.new(0, 15, 0, 15))
local DecalButton = CreateButton("Decal", UDim2.new(0, 220, 0, 15))
local ThemeButton = CreateButton("Theme", UDim2.new(0, 15, 0, 90))
